// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendAmount, address actor, uint8 reverterSeed) public {
        // Bound amounts to reasonable range, keep wide
        amount = bound(amount, 1, 1000 ether);
        sendAmount = bound(sendAmount, 1, 1000 ether);
        // Ensure actor is not the test contract and not zero
        vm.assume(actor != address(0) && actor != address(this));
        // Deploy adversarial Reverter contract with fuzzed address seed
        vm.prank(actor);
        Reverter reverter = new Reverter();
        // Fund actor and give some balance to reverter via deposit to C
        vm.deal(actor, amount);
        vm.prank(actor);
        c.fallback{value: amount}();
        // Now set the reverter's balance in C by deposit
        vm.deal(address(reverter), sendAmount);
        vm.prank(address(reverter));
        c.fallback{value: sendAmount}();
        // Now withdraw from reverter - it will fail
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        // After the call, check C's invariant:
        // For reference: either the call reverted (ok=false) and balances unchanged,
        // or it succeeded and reverter's balance is zero AND reverter received sendAmount.
        // The bug mutates this: on failed send, it clears balance without revert.
        // Thus property: (ok == false) implies balances[reverter] == sendAmount
        // Violated by mutant because it succeeds (ok=true) while clearing balance without transfer.
        uint256 bal = c.balances(address(reverter));
        if (!ok) {
            assertTrue(bal == sendAmount);
        } else {
            // Reference always transfers successfully, so reverter balance must be 0
            // and ETH received; but mutant may have cleared balance without transfer.
            // We don't assert on ok==true path for mutant to fail on, instead:
            // The actual distinction: check that ok && (bal != 0) is impossible for ref,
            // but mutant can have ok && bal == 0 (balance cleared) without ETH sent.
            // Better: the ref always reverts on failed send because require enforces it.
            // For ref, ok is always true for Reverter? No, Reverter reverts on receive,
            // making the low-level call fail. Ref's require fails -> revert. So ok=false for ref.
            // For mutant: low-level call fails, no require, clears balance -> ok=true.
            // So invariant: ok == false for Reverter on reference.
            // We assert: ok == false for any input? The fuzzer can find a reverter making it false.
            // For generality: if the counterparty is a contract that reverts on receive,
            // the reference must revert. The bug succeeds silently.
            // So assert: !ok (reference property) - but that's not a "GENERAL rule" for every input.
            // Need a rule: For every adversary that reverts on receive, reference reverts.
            // We can assert: if (address(reverter).balance == sendAmount before?) No.
            // The rule: after any withdraw by a contract that reverts on receive, the reference
            // reverts, and the bug does not. So property: (call did not revert) => balances[caller] == 0? No.
            // The reference's rule: either revert, or balances[caller]==0 AND caller received ETH.
            // The bug breaks: non-revert AND balances[caller]==0 AND caller did not receive ETH.
            // Hard to assert on ETH. But we can assert: if the caller is a contract that always
            // reverts on receive, then the reference MUST revert.
            // Here Reverter seeded with reverterSeed just to have deterministic addr difference.
            // Since we only need ONE assertion that holds for all fuzzed inputs for reference,
            // and fails for some on mutant: we can assert that for the Reverter contract,
            // the withdraw call MUST revert (ok == false).
            // For reference: always true (reverter fallback reverts -> send fails -> require fails).
            // For mutant: send fails but no require -> ok = true, balance = 0, assertion fails.
            assertTrue(!ok);
        }
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}

