pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackAmount) public {
        vm.assume(amount > 0 && amount < 1e18);
        vm.assume(attackAmount > 0 && attackAmount <= amount);
        Attacker attacker = new Attacker(c);
        vm.deal(address(c), amount);
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.fallback{value: amount}();
        attacker.attack(attackAmount);
        uint256 attackerBalance = c.balances(address(attacker));
        assertTrue(attackerBalance == 0);
    }
}

contract Attacker {
    C public target;
    uint256 private attackAmount;
    constructor(C _target) { target = _target; }
    function attack(uint256 _attackAmount) external {
        attackAmount = _attackAmount;
        target.withdraw();
    }
    receive() external payable {
        if (attackAmount > 0) {
            uint256 callAmount = attackAmount;
            attackAmount = 0;
            target.withdraw{value: callAmount}();
        }
    }
}

