pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint88 amount, uint88 initial) public {
        // Bound amounts to prevent overflow/insufficient balance, keeping domain wide.
        uint256 amt = bound(uint256(amount), 1, type(uint88).max);
        uint256 init = bound(uint256(initial), 1, type(uint88).max);
        vm.assume(caller != address(c) && caller != address(0));

        // Deploy a re-entrant attacker helper that calls withdraw again when receiving ETH.
        ReEntrantAttacker attacker = new ReEntrantAttacker(c);
        address attackAddr = address(attacker);

        // Fund the attacker and deposit into C via its fallback.
        vm.deal(attackAddr, init + amt);
        vm.prank(attackAddr);
        (bool ok,) = address(c).call{value: init}("");
        require(ok, "deposit failed");

        // Give the attacker additional ETH to pay for the withdrawal call, and trigger withdraw.
        vm.startPrank(attackAddr);
        uint256 preBal = address(c).balance;
        // The attacker's receive function will re-enter call withdraw once more.
        c.withdraw();
        vm.stopPrank();

        // Invariant: contract ETH balance should be at least the sum of all recorded balances.
        // After a re-entrant attack on the buggy version, this will be violated (balance lower than recorded sum).
        uint256 totalRecorded = c.balances(attackAddr);
        assertTrue(address(c).balance >= totalRecorded);
    }
}

contract ReEntrantAttacker {
    C public target;
    bool private entered;
    constructor(C _target) { target = _target; }
    receive() external payable {
        if (!entered && address(target).balance > 0) {
            entered = true;
            target.withdraw();
        }
    }
}

