pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 attackerRatio) public {
        // Bound the deposit amount to a reasonable range to avoid overflow
        amount = bound(amount, 1, 100 ether);
        // attackerRatio controls how much the attacker tries to drain in the reentrant call
        // Bound it to at least 1 to ensure a re-entrant attempt, and at most 255
        attackerRatio = uint8(bound(uint256(attackerRatio), 1, 255));

        // Deploy an adversarial re-entrant caller
        Attacker attacker = new Attacker(address(c));
        // Fund the attacker with Ether
        vm.deal(address(attacker), amount);

        // Attacker deposits Ether into C
        vm.prank(address(attacker));
        (bool success, ) = address(c).call{value: amount}("");
        require(success, "Deposit failed");

        // Record the state before withdraw
        uint256 contractBalanceBefore = address(c).balance;
        uint256 totalDepositsBefore = c.balances(address(attacker));

        // Attacker triggers withdraw, which may re-enter via receive and call withdraw again
        vm.prank(address(attacker));
        attacker.attack(attackerRatio);

        // Assert: after withdraw, the contract's ETH balance must equal the sum of all recorded balances
        // Because the attacker's balance is the only non-zero one, we check:
        // contractBalance == totalDeposits + any other balances (here only attacker's)
        // General invariant: address(c).balance == sum of balances for all addresses.
        // Since only attacker has a balance initially and attacker's balance may be drained,
        // we check that the invariant holds directly.
        assertTrue(address(c).balance == c.balances(address(attacker)));
    }
}

contract Attacker {
    C public target;
    bool private attacking;

    constructor(address _target) {
        target = C(_target);
        attacking = false;
    }

    function attack(uint8 ratio) external {
        attacking = true;
        target.withdraw();
        attacking = false;
    }

    receive() external payable {
        if (attacking && address(target).balance > 0) {
            // Re-enter withdraw
            target.withdraw();
        }
    }
}

