pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackerAmount) public {
        // restrict amounts to avoid overflow and ensure they are positive
        vm.assume(amount > 0 && amount <= 1e24);
        vm.assume(attackerAmount > 0 && attackerAmount <= 1e24);

        // deploy the re-entrant attacker that will call withdraw again in its receive function
        ReentrantAttacker attacker = new ReentrantAttacker();

        // give ETH to the attacker and deposit into the contract
        vm.deal(address(attacker), attackerAmount);
        vm.prank(address(attacker));
        (bool sent,) = address(c).call{value: attackerAmount}("");
        require(sent, "deposit failed");

        // attacker calls withdraw, which triggers re-entrancy
        vm.prank(address(attacker));
        attacker.attack(c, amount);

        // After the attack completes, the attacker's recorded balance in the contract must be zero
        // The reference contract's lock modifier prevents the re-entrancy, so balances[attacker] becomes 0.
        // The buggy contract allows the re-entrant call, leaving the recorded balance > 0.
        assertTrue(c.balances(address(attacker)) == 0);
    }
}

contract ReentrantAttacker {
    bool private attacking;
    function attack(C target, uint256 amount) external {
        attacking = true;
        target.withdraw();
        attacking = false;
    }
    receive() external payable {
        if (attacking && address(msg.sender).balance >= 0) {
            attacking = false;
            C(msg.sender).withdraw();
        }
    }
}

