pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 reenterAmount) public {
        vm.assume(amount > 0);
        vm.assume(reenterAmount > 0);
        vm.assume(amount + reenterAmount < type(uint256).max);

        Attacker attacker = new Attacker(c);
        vm.deal(address(attacker), amount + reenterAmount);

        // Deposit into C via the attacker
        attacker.deposit{value: amount + reenterAmount}();

        // Trigger withdraw through the attacker, which re-enters
        attacker.attack();

        // After attack completes, the attacker's balance in C must be zero
        uint256 attackerBalance = c.balances(address(attacker));
        assertTrue(attackerBalance == 0);
    }
}

contract Attacker {
    C public target;
    bool private reentered;

    constructor(C _target) {
        target = _target;
    }

    function deposit() external payable {
        // forward to fallback
        (bool ok, ) = address(target).call{value: msg.value}("");
        require(ok);
    }

    function attack() external {
        target.withdraw();
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Re-enter withdraw if we still have a recorded balance
            if (target.balances(address(this)) > 0) {
                target.withdraw();
            }
        }
    }
}

contract InvMutTest {
