    address user1;
    address user2;

    constructor(C _c) {
        c = _c;
        user1 = address(0x1);
        user2 = address(0x2);
    }

    function test(uint256 amount1, uint256 amount2) public payable {
        require(amount1 > 0 && amount2 > 0);
        require(address(this).balance >= amount1 + amount2);

        (bool ok1, ) = address(c).call{value: amount1}(hex"");
        require(ok1);
        (bool ok2, ) = address(c).call{value: amount2}(hex"");
        require(ok2);

        c.withdraw();

        assert(address(c).balance == c.balances(user1) + c.balances(user2));
    }
}

