        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }
        uint contractBalanceAfter = address(c).balance;
        assert(!reverted && balanceBefore > 0 ? contractBalanceBefore - contractBalanceAfter == balanceBefore : true);
    }
    receive() external payable {}
}

